fixtureSources.test/discovery-output.test.ts:
import { expect, test } from "bun:test";
import type { DiscoveryFinding } from "../src/discovery.js";
import type { DispatcherResult } from "../src/dispatcher.js";
import {
	formatDispatcherResult,
	sourceBlockLabel,
	sourceBlockLines,
	sourceBlocks,
} from "../src/discovery-output.js";

function finding(
	overrides: Partial<DiscoveryFinding> & { path: string },
): DiscoveryFinding {
	return { via: "grep", ...overrides };
}

function result(overrides: Partial<DispatcherResult> = {}): DispatcherResult {
	return {
		status: "finished",
		results: [],
		toolCalls: 12,
		decisions: 4,
		elapsedMs: 8200,
		findings: [],
		warnings: [],
		remainingTasks: [],
		...overrides,
	};
}

test("overlapping agreeing findings coalesce into one exact block", () => {
	const blocks = sourceBlocks([
		finding({
			path: "src/a.ts",
			line: 10,
			endLine: 12,
			text: "10|alpha\n11|beta\n12|gamma",
			relevance: 0.9,
		}),
		finding({
			path: "src/a.ts",
			line: 11,
			endLine: 14,
			text: "11|beta\n12|gamma\n13|delta\n14|epsilon",
			via: "read",
			relevance: 0.8,
		}),
	]);
	expect(blocks).toHaveLength(1);
	expect(blocks[0]!.segments).toEqual([{ start: 10, end: 14 }]);
	expect(blocks[0]!.lines).toEqual([
		{ line: 10, content: "alpha" },
		{ line: 11, content: "beta" },
		{ line: 12, content: "gamma" },
		{ line: 13, content: "delta" },
		{ line: 14, content: "epsilon" },
	]);
	expect(blocks[0]!.via).toEqual(["grep", "read"]);
	expect(blocks[0]!.relevance).toBe(0.9);
});

test("disjoint ranges stay separate segments with an elision marker", () => {
	const blocks = sourceBlocks([
		finding({ path: "src/a.ts", line: 10, text: "10|one\n11|two" }),
		finding({ path: "src/a.ts", line: 20, text: "20|three" }),
	]);
	expect(blocks).toHaveLength(1);
	expect(blocks[0]!.segments).toEqual([
		{ start: 10, end: 11 },
		{ start: 20, end: 20 },
	]);
	expect(sourceBlockLines(blocks[0]!)).toEqual([
		"10|one",
		"11|two",
		"…",
		"20|three",
	]);
});

test("conflicting overlapping source is not silently merged", () => {
	const blocks = sourceBlocks([
		finding({ path: "src/a.ts", line: 10, text: "10|left" }),
		finding({
			path: "src/a.ts",
			line: 10,
			endLine: 11,
			text: "10|right\n11|other",
		}),
	]);
	expect(blocks).toHaveLength(2);
	expect(sourceBlockLines(blocks[0]!)).toEqual(["10|left"]);
	expect(sourceBlockLines(blocks[1]!)).toEqual(["10|right", "11|other"]);
});

test("relevance ranks blocks first and unranked partial evidence stays marked", () => {
	const blocks = sourceBlocks([
		finding({ path: "b.ts", line: 1 }),
		finding({ path: "c.ts", line: 1, relevance: 0.7 }),
		finding({ path: "a.ts", line: 1, relevance: 0.9 }),
	]);
	expect(blocks.map((block) => block.path)).toEqual(["a.ts", "c.ts", "b.ts"]);
	expect(blocks[2]!.relevance).toBeUndefined();
	expect(sourceBlockLabel(blocks[2]!)).toContain("unranked");
	expect(sourceBlockLabel(blocks[0]!)).toContain("relevance 0.90");
});

test("single numbered-looking row is only trusted when it matches its anchor", () => {
	const mismatched = sourceBlocks([
		finding({ path: "data.txt", line: 5, text: "99|123|fallback" }),
	]);
	expect(mismatched[0]!.lines).toEqual([
		{ line: 5, content: "99|123|fallback" },
	]);
	const trusted = sourceBlocks([
		finding({ path: "src/a.ts", line: 7, text: "7|matched" }),
	]);
	expect(trusted[0]!.lines).toEqual([{ line: 7, content: "matched" }]);
});

test("aborted results never read as complete and keep the abort notice", () => {
	const output = formatDispatcherResult(
		result({
			status: "aborted",
			findings: [finding({ path: "src/a.ts", line: 3, text: "3|hit" })],
			warnings: [
				"Cancelled; collected locations are partial. Remaining tasks were not completed.",
			],
		}),
	);
	expect(output).toContain("aborted before completion; findings are partial");
	expect(output).toContain("Cancelled; collected locations are partial");
	expect(output).toContain("3|hit");
	expect(output).not.toContain("finished");
	expect(output).not.toContain('"findings"');
	expect(output.match(/3\|hit/g)).toHaveLength(1);
});

test("escalated results surface unresolved work", () => {
	const output = formatDispatcherResult(
		result({
			status: "escalated",
			results: [
				{
					task: { id: "routes", description: "Read the refresh flow" },
					status: "REQUIRE_BIGGER_MODEL",
					summary: "Jev requested a larger model; no model was spawned.",
					evidence: [],
					findings: [],
				},
			],
			remainingTasks: [{ id: "tests", description: "Find tests for refresh" }],
		}),
	);
	expect(output).toContain("escalated; unresolved tasks need a larger model");
	expect(output).toContain("routes: needs a larger model");
	expect(output).toContain("Not attempted (unresolved):");
	expect(output).toContain("tests: Find tests for refresh");
});

test("raw outcome evidence is a fallback only when no findings exist", () => {
	const withFindings = formatDispatcherResult(
		result({
			findings: [finding({ path: "src/a.ts", line: 3, text: "3|hit" })],
			results: [
				{
					task: { id: "t1", description: "d" },
					status: "TASK_FINISHED",
					summary: "done",
					evidence: ["--- grep x ---\n3|hit"],
					findings: [],
				},
			],
		}),
	);
	const withoutFindings = formatDispatcherResult(
		result({
			results: [
				{
					task: { id: "t1", description: "d" },
					status: "NO_PATH",
					summary: "nothing",
					evidence: ["--- grep x ---\nno matches"],
					findings: [],
				},
			],
		}),
	);
	expect(withFindings).not.toContain("--- grep x ---");
	expect(withoutFindings).toContain(
		"No locations found in the searched scope.",
	);
	expect(withoutFindings).toContain("Retained evidence:");
	expect(withoutFindings).toContain("--- grep x ---");
});

test("oversized output is bounded with explicit omissions and keeps abort notices", () => {
	const pad = "filler ".repeat(200);
	const findings = Array.from({ length: 3 }, (_, index) =>
		finding({
			path: `src/file${index}.ts`,
			line: 1,
			text: Array.from({ length: 2000 }, (_, line) => `${line + 1}|x`).join(
				"\n",
			),
			relevance: 0.5,
		}),
	);
	const warnings = Array.from(
		{ length: 20 },
		(_, index) => `note ${index}: ${pad}`,
	);
	warnings[0] = "aborted: discovery cancelled mid-run";
	const output = formatDispatcherResult(result({ findings, warnings }));
	expect(output.length).toBeLessThanOrEqual(12_000);
	expect(output).toContain("more locations omitted for length");
	expect(output).toContain("more warnings omitted");
	expect(output).toContain("aborted: discovery cancelled mid-run");
});

fixtureSources.test/discovery-ranking.test.ts:
import { expect, test } from "bun:test";
import {
	directoryKey,
	rankFiles,
	searchTerms,
} from "../src/discovery-ranking.js";

// Pure term-extraction and ranking-key contracts shared with the dispatcher:
// boilerplate removal, identifier preservation, modest stemming, and the
// directory-key shape used for semantic priorities.

test("directoryKey keeps the first two directory segments", () => {
	expect(directoryKey("src/lib/util.ts")).toBe("src/lib");
	expect(directoryKey("src/util.ts")).toBe("src");
	expect(directoryKey("util.ts")).toBe(".");
	expect(directoryKey("./util.ts")).toBe(".");
	expect(directoryKey("src\\lib\\util.ts")).toBe("src/lib");
	expect(directoryKey("src/lib/")).toBe("src/lib");
});

test("searchTerms preserves identifiers and quoted phrases verbatim", () => {
	expect(searchTerms("fix getUserData_fromCache v2 renderState")).toEqual([
		"fix",
		"getuserdata_fromcache",
		"v2",
		"renderstate",
	]);
	// Quoted phrases survive even when they are pure boilerplate words.
	expect(searchTerms('show the "read" handling')).toEqual(["read", "handl"]);
	expect(searchTerms("API JSON doing things")).toEqual([
		"api",
		"json",
		"doing",
		"thing",
	]);
});

test("searchTerms yields nothing for pure boilerplate and caps at 12 terms", () => {
	expect(searchTerms("the of and to")).toEqual([]);
	expect(searchTerms("   ")).toEqual([]);
	expect(
		searchTerms(Array.from({ length: 30 }, (_, i) => `term${i}`).join(" ")),
	).toHaveLength(12);
});

test("a concentrated implementation outranks scattered terms despite a weak introductory match", () => {
	const candidates = new Map([
		[
			"a.ts",
			[
				{ line: 10, text: "purchase" },
				{ line: 30, text: "cancel" },
			],
		],
		[
			"b.ts",
			[
				{ line: 1, text: "purchase" },
				{ line: 100, text: "purchase cancel" },
			],
		],
	]);
	expect(
		rankFiles(candidates, ["purchase", "cancel"], "purchase cancel")[0].path,
	).toBe("b.ts");
});

fixtureSources.test/settings.test.ts:
import { afterEach, test } from "bun:test";
import assert from "node:assert/strict";
import {
	mkdir,
	mkdtemp,
	readFile,
	readdir,
	rm,
	stat,
	writeFile,
} from "node:fs/promises";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { configCli, editorArgv } from "../src/config-cli.js";
import { loadConfig, loadRules } from "../src/config.js";
import { configPaths } from "../src/paths.js";
import {
	initializeDocuments,
	loadOrchestrator,
	validateSettings,
} from "../src/settings.js";

const cleanup: Array<() => void | Promise<void>> = [];
afterEach(async () => {
	for (const fn of cleanup.splice(0).reverse()) await fn();
});
async function fixture() {
	const root = await mkdtemp(join(tmpdir(), "jev settings "));
	cleanup.push(() => rm(root, { recursive: true, force: true }));
	const paths = configPaths(
		join(root, "project"),
		join(root, "legacy"),
		join(root, "global configs"),
	);
	await mkdir(join(root, "project"), { recursive: true });
	const put = async (path: string, value: unknown) => {
		await mkdir(dirname(path), { recursive: true });
		await writeFile(path, JSON.stringify(value));
	};
	return { root, paths, put };
}
test("init creates every config with private permissions and never overwrites edits", async () => {
	const { paths, put } = await fixture();
	assert.equal((await initializeDocuments(paths, "global")).length, 3);
	for (const path of Object.values(paths.global))
		assert.equal((await stat(path)).mode & 0o777, 0o600);
	await put(paths.global.orchestrator, { models: { strong: "my/model" } });
	assert.deepEqual(await initializeDocuments(paths, "global"), []);
	assert.equal(
		(await loadOrchestrator(paths.orchestrator)).models.strong,
		"my/model",
	);
	await validateSettings(paths);
});
test("legacy migration excludes project overrides and keeps legacy source untouched", async () => {
	const { paths, put } = await fixture();
	await put(paths.config[0], { client: { timeoutMs: 4200 } });
	await put(paths.project.main, { client: { timeoutMs: 900 } });
	const legacy = await readFile(paths.config[0], "utf8");
	await initializeDocuments(paths, "global");
	assert.equal(
		JSON.parse(await readFile(paths.global.main, "utf8")).client.timeoutMs,
		4200,
	);
	assert.equal((await loadConfig(paths.config)).client.timeoutMs, 900);
	assert.equal(await readFile(paths.config[0], "utf8"), legacy);
});
test("project init produces partial overlays that keep inheriting global changes", async () => {
	const { paths, put } = await fixture();
	await initializeDocuments(paths, "project");
	assert.deepEqual(
		JSON.parse(await readFile(paths.project.orchestrator, "utf8")),
		{ version: 1 },
	);
	await put(paths.global.orchestrator, {
		models: { strong: "custom/strong" },
		timeoutMs: 800,
	});
	assert.equal(
		(await loadOrchestrator(paths.orchestrator)).models.strong,
		"custom/strong",
	);
	await put(paths.project.orchestrator, {
		models: { reviewer: "custom/reviewer" },
	});
	assert.equal((await loadOrchestrator(paths.orchestrator)).timeoutMs, 800);
	assert.equal(
		(await loadOrchestrator(paths.orchestrator)).models.reviewer,
		"custom/reviewer",
	);
});
test("rules migrate by ID and project IDs still override global IDs", async () => {
	const { paths, put } = await fixture();
	const rule = (message: string) => ({
		id: "rule",
		events: ["manual"],
		question: { type: "noul", instructions: "Relevant?" },
		outcomes: [{ when: { min: 0.9 }, action: { type: "message", message } }],
	});
	await put(paths.rules[0], { version: 1, rules: [rule("legacy")] });
	await put(paths.project.rules, { version: 1, rules: [rule("project")] });
	await initializeDocuments(paths, "global");
	assert.equal(
		(await loadRules([paths.global.rules]))[0].outcomes[0].action.message,
		"legacy",
	);
	assert.equal(
		(await loadRules(paths.rules))[0].outcomes[0].action.message,
		"project",
	);
});
test("malformed files are not overwritten and validation reports the file", async () => {
	const { paths } = await fixture();
	await initializeDocuments(paths, "global");
	await writeFile(paths.global.orchestrator, "{broken");
	assert.deepEqual(await initializeDocuments(paths, "global"), []);
	await assert.rejects(() => validateSettings(paths), /orchestrator.json/);
});
test("editor parser supports flags and quoted paths without shell expansion", () => {
	assert.deepEqual(editorArgv('"/my editor" --wait "a b"'), [
		"/my editor",
		"--wait",
		"a b",
	]);
	assert.deepEqual(editorArgv("nano '$(touch unsafe)'"), [
		"nano",
		"$(touch unsafe)",
	]);
	assert.throws(() => editorArgv('nano "broken'), /Unclosed/);
