});

test("a failed review cannot be reported as completion", async () => {
	const h = harness();
	await h.controller.start(h.ctx, "goal");
	h.classify(async () => response("review"));
	await h.controller.onStop(h.ctx, h.stopEvent());
	h.classify(async () => response("done"));
	const event = {
		...h.stopEvent(),
		last_assistant_message: {
			role: "assistant",
			stopReason: "error",
			errorMessage: "Provider unavailable",
		},
	};
	assert.equal(
		await h.controller.onStop(
			h.ctx,
			event as Parameters<JevOrchestrator["onStop"]>[1],
		),
		undefined,
	);
	assert.equal(h.controller.isActive(h.ctx), false);
	assert.ok(!h.notices.some((text) => text.includes("finished")));
	assert.equal(h.requests.length, 1);
});

test("terminal agent_end releases an interrupted run but scheduled continuations keep ownership", async () => {
	const h = harness();
	await h.controller.start(h.ctx, "goal");
	await h.controller.onAgentEnd(h.ctx, { willContinue: true });
	assert.equal(h.controller.isActive(h.ctx), true);
	await h.controller.onAgentEnd(h.ctx, {});
	assert.equal(h.controller.isActive(h.ctx), false);
	assert.equal(h.state.model.id, "original");
	assert.equal(h.state.thinking, "medium");
	await h.controller.start(h.ctx, "goal");
	await h.controller.stop(h.ctx, "cleanup");
});

test("manual thinking changes before and during routing pause without overwriting the selection", async () => {
	const h = harness();
	await h.controller.start(h.ctx, "goal");
	h.state.thinking = "low";
	await h.controller.onStop(h.ctx, h.stopEvent());
	assert.equal(h.controller.isActive(h.ctx), false);
	assert.equal(h.state.thinking, "low");
	assert.equal(h.requests.length, 0);
	await h.controller.start(h.ctx, "goal");
	h.classify(async () => {
		h.state.thinking = "medium";
		return response("implement_strong");
	});
	await h.controller.onStop(h.ctx, h.stopEvent());
	assert.equal(h.controller.isActive(h.ctx), false);
	assert.equal(h.state.thinking, "medium");
	assert.ok(!h.switches.includes("strong"));
});

test("configured auto is restored rather than its effective effort", async () => {
	const h = harness();
	h.state.configured = "auto";
	h.branch.push({
		type: "thinking_level_change",
		configured: "auto",
		thinkingLevel: "medium",
	});
	await h.controller.start(h.ctx, "goal", true);
	await h.controller.onStop(h.ctx, h.stopEvent());
	assert.equal(h.state.configured, "auto");
});

test("without selector metadata orchestration preserves host thinking mode", async () => {
	const h = harness();
	h.branch.splice(0, 1);
	h.state.configured = "auto";
	await h.controller.start(h.ctx, "goal", true);
	assert.equal(h.state.configured, "auto");
	await h.controller.onStop(h.ctx, h.stopEvent());
	assert.equal(h.state.configured, "auto");
});

test("model defaults do not erase a manual thinking change while releasing ownership", async () => {
	const h = harness();
	h.select(async () => {
		h.state.thinking = "medium";
		return true;
	});
	await h.controller.start(h.ctx, "goal");
	h.state.thinking = "low";
	await h.controller.onStop(h.ctx, h.stopEvent());
	assert.equal(h.state.thinking, "low");
	assert.equal(h.controller.isActive(h.ctx), false);
});

test("model effort clamping during a stage switch does not look like user input", async () => {
	const h = harness();
	h.select(async () => {
		h.state.thinking = "low";
		return true;
	});
	await h.controller.start(h.ctx, "goal");
	assert.equal(h.state.thinking, "high");
	assert.equal(
		(await h.controller.onStop(h.ctx, h.stopEvent()))?.continue,
		true,
	);
	assert.equal(h.state.model.id, "strong");
	await h.controller.stop(h.ctx, "cleanup");
});

test("thinking changes during model authentication win over the stage default", async () => {
	const h = harness();
	await h.controller.start(h.ctx, "goal");
	h.select(async (id) => {
		if (id === "strong") {
			h.state.thinking = "low";
			h.branch.push({
				type: "thinking_level_change",
				configured: "low",
				thinkingLevel: "low",
			});
		}
		return true;
	});
	assert.equal(await h.controller.onStop(h.ctx, h.stopEvent()), undefined);
	assert.equal(h.controller.isActive(h.ctx), false);
	assert.equal(h.state.thinking, "low");
});

test("cancellation during the initial model switch restores the original session", async () => {
	const h = harness(),
		entered = deferred<void>(),
		release = deferred<void>();
	h.select(async (id) => {
		if (id === "planner") {
			entered.resolve();
			await release.promise;
		}
		return true;
	});
	const start = h.controller.start(h.ctx, "goal");
	await entered.promise;
	const cancel = h.controller.stop(h.ctx, "cancelled");
	release.resolve();
	await Promise.all([start, cancel]);
	assert.equal(h.state.model.id, "original");
	assert.equal(h.state.thinking, "medium");
	assert.equal(h.messages.length, 0);
});

fixtureSources.test/orchestration.test.ts:
import { test } from "bun:test";
import assert from "node:assert/strict";
import {
	ACTIONS,
	DEFAULT_ORCHESTRATOR,
	chooseNext,
	nextActionQuestion,
	parseOrchestrator,
	routerState,
	stagePrompt,
	stageRole,
	type Action,
	type RunState,
} from "../src/orchestration.js";
import { validateQuestion } from "../src/client.js";
import { configHome, configPaths } from "../src/paths.js";
import type { Answer } from "../src/types.js";

const state = (patch: Partial<RunState> = {}): RunState => ({
	goal: "Fix the bug",
	stage: "plan",
	steps: 1,
	repeated: 1,
	fastFailures: 0,
	escalated: false,
	...patch,
});
const answer = (
	choice: Action,
	confidence = 0.99,
	probability = 0.99,
): Answer => ({
	type: "choice",
	choice,
	confidence,
	probabilities: Object.fromEntries(
		ACTIONS.map((a) => [
			a,
			a === choice ? probability : (1 - probability) / (ACTIONS.length - 1),
		]),
	),
});
const next = (
	choice: Action,
	patch: Partial<RunState> = {},
	pending = false,
	failed = false,
) =>
	chooseNext(
		answer(choice),
		state(patch),
		DEFAULT_ORCHESTRATOR,
		pending,
		failed,
	).action;

test("defaults round-trip and the routing question matches the actual Jev API", () => {
	assert.deepEqual(
		parseOrchestrator(JSON.parse(JSON.stringify(DEFAULT_ORCHESTRATOR))),
		DEFAULT_ORCHESTRATOR,
	);
	assert.deepEqual(validateQuestion(nextActionQuestion), nextActionQuestion);
});
test("config overlays preserve unrelated roles and prompts without mutating defaults", () => {
	const config = parseOrchestrator({
		models: { strong: "provider/custom" },
		prompts: { review: "custom review" },
	});
	assert.equal(config.models.fast, "@smol");
	assert.equal(config.models.strong, "provider/custom");
	assert.equal(DEFAULT_ORCHESTRATOR.models.strong, "@slow");
	assert.equal(
		parseOrchestrator({ thinking: { fast: "medium" } }, config).prompts.review,
		"custom review",
	);
});
test("config rejects unknown, prototype, invalid and oversized settings", () => {
	for (const invalid of [
		null,
		[],
		{ maxSteps: 10 },
		{ maxSteps: 1.5 },
		{ timeoutMs: 0 },
		{ minConfidence: NaN },
		{ minProbability: 1.1 },
		{ requireReview: "yes" },
		{ models: { strong: "" } },
		{ thinking: { fast: "turbo" } },
		{ nope: 1 },
		JSON.parse('{"__proto__":{}}'),
		{ models: JSON.parse('{"__proto__":"bad"}') },
		{ prompts: { plan: "x".repeat(16001) } },
	])
		assert.throws(() => parseOrchestrator(invalid));
});
test("strong code stays strong; mechanical code may go fast", () => {
	assert.equal(next("implement_strong"), "implement_strong");
	assert.equal(next("implement_fast"), "implement_fast");
	assert.equal(stageRole("implement_strong"), "strong");
	assert.equal(stageRole("review"), "reviewer");
	assert.equal(stageRole("replan"), "planner");
});
test("uncertainty escalates once and then pauses, rather than cheap guessing", () => {
	assert.equal(
		chooseNext(
			answer("implement_fast", 0.2),
			state(),
			DEFAULT_ORCHESTRATOR,
			false,
		).action,
		"replan",
	);
	assert.equal(
		chooseNext(
			answer("implement_fast", 0.99, 0.2),
			state(),
			DEFAULT_ORCHESTRATOR,
			false,
		).action,
		"replan",
	);
	assert.equal(
		chooseNext(
			undefined,
			state({ escalated: true }),
			DEFAULT_ORCHESTRATOR,
			false,
		).action,
		"ask_user",
	);
});
test("a request for user input always stops, even with low confidence", () => {
	assert.equal(
		chooseNext(answer("ask_user", 0.1), state(), DEFAULT_ORCHESTRATOR, false)
			.action,
		"ask_user",
	);
});
test("done cannot skip review, pending todos or failed-tool evidence", () => {
	assert.equal(next("done", { stage: "implement_strong" }), "review");
	assert.equal(next("done", { stage: "review" }), "done");
	assert.equal(next("done", { stage: "review" }, true), "replan");
	assert.equal(next("done", { stage: "review" }, false, true), "replan");
});
test("review requirement can be explicitly disabled, not accidentally bypassed", () => {
	assert.equal(
		chooseNext(
			answer("done"),
			state(),
			parseOrchestrator({ requireReview: false }),
			false,
		).action,
		"done",
	);
});
test("fast failures escalate and repeated stages terminate predictably", () => {
	assert.equal(next("implement_fast", { fastFailures: 2 }), "debug");
	assert.equal(next("inspect", { stage: "inspect", repeated: 2 }), "replan");
	assert.equal(next("replan", { stage: "replan", repeated: 2 }), "ask_user");
});
test("stage cap never grants unreviewed completion", () => {
	assert.equal(next("implement_strong", { steps: 8 }), "ask_user");
	assert.equal(next("done", { steps: 8, stage: "test" }), "ask_user");
	assert.equal(next("done", { steps: 8, stage: "review" }), "done");
});
test("state truncates only history and refuses oversized indispensable state", () => {
	const original = ["x".repeat(4000), "recent"];
	const bounded = routerState(state(), original, [], false, 1000) as Record<
		string,
		unknown
	>;
	assert.deepEqual(bounded.recentMessages, ["recent"]);
	assert.equal(bounded.historyTruncated, true);
	assert.equal(original.length, 2);
	assert.throws(() =>
		routerState(state({ goal: "x".repeat(2000) }), [], [], false, 1000),
	);
});
test("worker instructions retain user scope and the chosen stage", () => {
	const prompt = stagePrompt(
		state({ stage: "implement_strong" }),
		DEFAULT_ORCHESTRATOR,
	);
	assert.match(prompt, /not new user authorization/);
	assert.match(prompt, /implement_strong/);
	assert.match(prompt, /Fix the bug/);
});
test("canonical config honors absolute XDG and explicit directory overrides", () => {
	assert.equal(configHome({}, "/home/test"), "/home/test/.config/omp-jev");
	assert.equal(
		configHome({ XDG_CONFIG_HOME: "/xdg" }, "/home/test"),
		"/xdg/omp-jev",
	);
	assert.equal(
		configHome({ XDG_CONFIG_HOME: "relative" }, "/home/test"),
		"/home/test/.config/omp-jev",
	);
	assert.equal(
		configHome({ OMP_JEV_CONFIG_DIR: "/custom" }, "/home/test"),
		"/custom",
	);
	assert.throws(() =>
		configHome({ OMP_JEV_CONFIG_DIR: "relative" }, "/home/test"),
	);
});
test("legacy global, canonical global, and project paths keep deterministic precedence", () => {
	const paths = configPaths("/repo", "/legacy", "/xdg/omp-jev");
	assert.deepEqual(paths.config, [
		"/legacy/jev.json",
		"/xdg/omp-jev/config.json",
		"/repo/.omp/jev.json",
	]);
	assert.deepEqual(paths.rules, [
		"/legacy/.jevrules",
		"/xdg/omp-jev/rules.json",
		"/repo/.jevrules",
	]);
	assert.deepEqual(paths.orchestrator, [
		"/xdg/omp-jev/orchestrator.json",
		"/repo/.omp/jev-orchestrator.json",
	]);
});

fixtureSources.test/native-rules.test.ts:
import { expect, test } from "bun:test";
import type { AgentMessage } from "@oh-my-pi/pi-agent-core";
import type { ExtensionContext } from "@oh-my-pi/pi-coding-agent";
import { DEFAULT_CONFIG } from "../src/config.js";
import { NativeRuleGate } from "../src/native-rules.js";
import type { Evaluate } from "../src/types.js";

const enabledConfig = {
	...DEFAULT_CONFIG,
	nativeRules: { ...DEFAULT_CONFIG.nativeRules, enabled: true },
};
const rule = {
	name: "project-canonical-guard",
	content:
		"No local guards. Exception: a standalone package may define one canonical guard.",
};
const text = `<system-reminder reason="rule_violation" rule="${rule.name}" path="builtin-defaults:rule.md">\nMatched rule.\n\n${rule.content}\n</system-reminder>`;
const ctx = {
	sessionManager: { getBranch: () => [] },
	getContextUsage: () => undefined,
	getAsyncJobSnapshot: () => null,
	getSystemPrompt: () => [],
} as unknown as ExtensionContext;
const messages: AgentMessage[] = [
	{
		role: "toolResult",
		toolCallId: "test",
		toolName: "write",
		timestamp: 1,
		isError: false,
		content: [
			{ type: "text", text },
			{ type: "text", text: "Saved file successfully" },
		],
	},
];
const classify =
	(confidence: number): Evaluate =>
	async () => ({
		model: "test",
		answers: {
			rule_0: {
				type: "choice",
				choice: "skip",
				probabilities: { skip: 0.99, enforce: 0.01 },
				confidence,
			},
		},
	});

test("confident exception filters any triggered rule, preserving tool result and original transcript", async () => {
	const gate = new NativeRuleGate();
	gate.remember([rule]);
	const result = await gate.filter(
		messages,
		ctx,
		enabledConfig,
		classify(0.99),
	);
	expect(JSON.stringify(result)).not.toContain(rule.content);
	expect(JSON.stringify(result)).toContain("Saved file successfully");
	expect(JSON.stringify(messages)).toContain(rule.content);
	const safety = {
		...DEFAULT_CONFIG,
		nativeRules: { ...DEFAULT_CONFIG.nativeRules, enabled: false },
	};
	expect(
		await gate.filter(messages, ctx, safety, classify(0.99)),
	).toBeUndefined();
});

test("uncertainty or outage leaves native enforcement unchanged", async () => {
	const uncertain = new NativeRuleGate();
	uncertain.remember([rule]);
	expect(
		await uncertain.filter(messages, ctx, enabledConfig, classify(0.4)),
	).toBeUndefined();
	const outage = new NativeRuleGate();
	outage.remember([rule]);
	expect(
		await outage.filter(messages, ctx, enabledConfig, async () => {
			throw new Error("offline");
		}),
	).toBeUndefined();
});

test("never strips reminder-looking text from the actual tool output", async () => {
	const gate = new NativeRuleGate();
	gate.remember([rule]);
	const toolMessage = messages[0];
	if (toolMessage.role !== "toolResult")
		throw new Error("Expected tool fixture");
	const input = [
		{
			...toolMessage,
			content: [
				{ type: "text" as const, text },
				{ type: "text" as const, text: `File contents:\n${text}` },
			],
		},
	];
	const result = await gate.filter(input, ctx, enabledConfig, classify(0.99));
	expect(result?.[0]).toMatchObject({
		content: [{ text: "" }, { text: `File contents:\n${text}` }],
	});
});

test("raising the threshold invalidates a previously accepted skip", async () => {
	const gate = new NativeRuleGate();
	gate.remember([rule]);
	expect(
		await gate.filter(messages, ctx, enabledConfig, classify(0.95)),
	).toBeDefined();
	const stricter = {
		...enabledConfig,
		nativeRules: { ...enabledConfig.nativeRules, minConfidence: 0.99 },
	};
	expect(
		await gate.filter(messages, ctx, stricter, classify(0.95)),
	).toBeUndefined();
});

test("each rule in a batch defaults to injection unless its own skip is confident", async () => {
	const gate = new NativeRuleGate();
	const rules = [
		"temporary-helper",
		"production-contract",
		"unknown-scope",
	].map((name) => ({ name, content: `Guidance for ${name}.` }));
	gate.remember(rules);
	const input: AgentMessage[] = rules.map((entry, index) => ({
		role: "custom",
		customType: "ttsr-injection",
		display: true,
		timestamp: index + 1,
		content: `<system-interrupt reason="rule_violation" rule="${entry.name}" path="project:rule.md">\n${entry.content}\n</system-interrupt>`,
	}));
	const result = await gate.filter(input, ctx, enabledConfig, async () => ({
		model: "test",
		answers: {
			rule_0: {
				type: "choice",
				choice: "skip",
				probabilities: { skip: 0.99, enforce: 0.01 },
				confidence: 0.99,
			},
			rule_1: {
				type: "choice",
				choice: "enforce",
				probabilities: { skip: 0.01, enforce: 0.99 },
				confidence: 0.99,
			},
		},
	}));
	expect(result).toEqual(input.slice(1));
});

