	test("rejects non-JSON state before any request", async () => {
		const s = serve(() => Response.json({ model: "m", answers: {} }));
		try {
			await expect(
				evaluate(config(s.endpoint), { at: new Date() } as unknown as Json, {
					q: NOUL,
				}),
