import { mkdir, readFile, writeFile, readdir } from 'node:fs/promises';
import { join } from 'node:path';
import { createHash } from 'node:crypto';
import { DEFAULT_ORCHESTRATOR, stagePrompt } from './fixture/src/orchestration.ts';

const root = import.meta.dir;
const fixture = join(root, 'fixture');
const cases = JSON.parse(await readFile(join(root, 'cases.json'), 'utf8')).cases;
const variant = process.argv[2] ?? 'reference';
const split = process.argv[3];
const selected = cases.filter((c: any) => !split || c.split === split);
const model = 'openai-codex/gpt-6-astra';
const folder = join(root, variant);
await mkdir(folder, { recursive: true });
async function hashes(dir = fixture, prefix = ''): Promise<Record<string, string>> {
  const result: Record<string, string> = {};
  for (const entry of await readdir(dir, { withFileTypes: true })) {
    const relative = prefix + entry.name;
    if (entry.isDirectory()) Object.assign(result, await hashes(join(dir, entry.name), relative + '/'));
    else if (entry.isFile()) result[relative] = createHash('sha256').update(await readFile(join(dir, entry.name))).digest('hex');
  }
  return result;
}
const before = await hashes();
if (!(await Bun.file(join(root, 'fixture-hashes.json')).exists())) await writeFile(join(root, 'fixture-hashes.json'), JSON.stringify(before, null, 2));
async function run(c: any) {
  const file = join(folder, c.id + '.json');
  if (await Bun.file(file).exists()) return;
  const prompt = variant === 'current'
    ? stagePrompt({ goal: c.goal, stage: 'plan', steps: 1, repeated: 1, fastFailures: 0, escalated: false }, DEFAULT_ORCHESTRATOR)
    : variant === 'handoff'
      ? `Produce a repository-grounded plan only. Inspect the relevant implementation and tests before deciding changes. Follow existing conventions for ordinary unspecified details; ask only for a material product decision or missing authorization. If the goal is already supported, say so and avoid redundant implementation.\n\nReturn the outcome (ready or needs_input), short source-supported findings with file:line citations, ordered tasks with stable IDs, dependencies and acceptance checks, and the single next ready task with its suggested role (inspect, implement_fast, implement_strong, test). Distinguish real dependencies from independent tasks that could run in parallel. If blocked, name the required decision rather than silently assuming it. This is a plan, not implementation or a claim that tests passed. Do not execute or delegate implementation.\n\nGoal: ${c.goal}`
      : c.goal;
  const args = ['pi', '--model', model, '--thinking', 'high', '--no-session', '--no-extensions', '--no-skills', '--no-context-files', '--no-prompt-templates', '--offline', '--tools', 'read,grep,find,ls', '--mode', 'json', '--append-system-prompt', 'This run is planning only. Inspect the repository using read-only tools. Do not implement or execute the proposed plan. Do not inspect files outside this repository. Return a source-grounded plan or explain the missing decision/authorization; do not invent APIs.', '--print', prompt];
  const start = performance.now();
  const proc = Bun.spawn(args, { cwd: fixture, stdout: 'pipe', stderr: 'pipe' });
  const timer = setTimeout(() => proc.kill('SIGTERM'), 240_000);
  const [stdout, stderr, exitCode] = await Promise.all([new Response(proc.stdout).text(), new Response(proc.stderr).text(), proc.exited]);
  clearTimeout(timer);
  const events = stdout.split('\n').flatMap(line => { try { return [JSON.parse(line)]; } catch { return []; } });
  const messages = events.filter(e => e.type === 'message_end').map(e => e.message);
  const assistants = messages.filter(m => m?.role === 'assistant');
  const last = assistants.at(-1);
  const text = (last?.content ?? []).filter((p: any) => p.type === 'text').map((p: any) => p.text).join('\n');
  const usage = assistants.reduce((a: any, m: any) => {
    for (const k of ['input', 'output', 'cacheRead', 'cacheWrite', 'totalTokens']) a[k] += m.usage?.[k] ?? 0;
    return a;
  }, { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, totalTokens: 0 });
  const tools = assistants.flatMap(m => (m.content ?? []).filter((p: any) => p.type === 'toolCall').map((p: any) => ({ name: p.name, arguments: p.arguments })));
  const result = { id: c.id, split: c.split, variant, model, thinking: 'high', goal: c.goal, elapsedMs: Math.round(performance.now() - start), characters: text.length, exitCode, stopReason: last?.stopReason, error: !text || exitCode !== 0 ? stderr.slice(-2000) : undefined, usage, tools, text };
  await writeFile(file, JSON.stringify(result, null, 2) + '\n');
  console.log(JSON.stringify({ id: c.id, variant, characters: text.length, elapsedMs: result.elapsedMs, exitCode, tools: tools.length, error: Boolean(result.error) }));
}
let next = 0;
await Promise.all(Array.from({ length: 3 }, async () => { while (next < selected.length) await run(selected[next++]); }));
const after = await hashes();
if (JSON.stringify(before) !== JSON.stringify(after)) throw new Error('Fixture changed during planning');
console.log(JSON.stringify({ variant, completed: selected.length, fixtureUnchanged: true, hashedFiles: Object.keys(before).length }));

