import { readFile, writeFile, mkdir, readdir } from 'node:fs/promises';
import { join } from 'node:path';
import { createHash } from 'node:crypto';
import extension from '../../home/jorge/.subvolumes/repos/omp-jev/src/extension.ts';

const root = import.meta.dir;
const fixture = join(root, 'fixture');
async function hashes(dir = fixture, prefix = ''): Promise<Record<string, string>> {
  const result: Record<string, string> = {};
  for (const entry of await readdir(dir, { withFileTypes: true })) {
    const relative = prefix + entry.name;
    if (entry.isDirectory()) Object.assign(result, await hashes(join(dir, entry.name), relative + '/'));
    else if (entry.isFile()) result[relative] = createHash('sha256').update(await readFile(join(dir, entry.name))).digest('hex');
  }
  return result;
}
export default function benchmark(pi: any) {
  const tools = new Map<string, any>();
  const commands = new Map<string, any>();
  const hooks = new Map<string, any>();
  const parentMessages: any[] = [];
  const parentSwitches: string[] = [];
  const wrapped = new Proxy(pi, {
    get(target, key) {
      if (key === 'registerTool') return (spec: any) => { tools.set(spec.name, spec); target.registerTool(spec); };
      if (key === 'registerCommand') return (name: string, spec: any) => { commands.set(name, spec); target.registerCommand(name, spec); };
      if (key === 'on') return (name: string, handler: any) => { hooks.set(name, handler); return target.on(name, handler); };
      if (key === 'sendMessage') return (message: any, options: any) => {
        parentMessages.push({ message, options });
        // Observe explicit execution handoff, but never dispatch a worker in this planning-only benchmark.
        if (message.customType === 'jev-orchestrator') return;
        return target.sendMessage(message, options);
      };
      if (key === 'setModel') return (model: any) => { parentSwitches.push(`${model.provider}/${model.id}`); return target.setModel(model); };
      return Reflect.get(target, key);
    }
  });
  extension(wrapped);
  pi.on('session_start', (_: any, ctx: any) => {
    void (async () => {
      const variant = process.env.JEV_BENCH_VARIANT ?? 'integrated';
      const split = process.env.JEV_BENCH_SPLIT ?? 'development';
      const mode = process.env.JEV_BENCH_MODE ?? 'benchmark';
      try {
        const all = JSON.parse(await readFile(join(root, 'cases.json'), 'utf8')).cases;
        const cases = all.filter((c: any) => c.split === split && (!process.env.JEV_BENCH_CASE || c.id === process.env.JEV_BENCH_CASE));
        const before = await hashes();
        const tool = tools.get('jev_plan');
        if (!tool) throw new Error('Planning tool is unavailable');
        const folder = join(root, variant);
        await mkdir(folder, { recursive: true });
        console.log(JSON.stringify({ benchmark: 'start', variant, split, mode, model: `${ctx.models.current()?.provider}/${ctx.models.current()?.id}`, thinking: pi.getThinkingLevel(), concurrency: tool.concurrency, approval: tool.approval }));
        const run = async (c: any, extra: any = {}, signal?: AbortSignal) => {
          const file = join(folder, c.id + '.json');
          if (mode === 'benchmark' && await Bun.file(file).exists()) return JSON.parse(await readFile(file, 'utf8'));
          const start = performance.now();
          try {
            const raw = await tool.execute('benchmark-' + c.id, { goal: c.goal, ...extra }, signal, undefined, ctx);
            const text = raw.content.filter((b: any) => b.type === 'text').map((b: any) => b.text).join('\n');
            const result = { id: c.id, split: c.split, variant, goal: c.goal, elapsedMs: Math.round(performance.now() - start), characters: text.length, completePayloadCharacters: JSON.stringify(raw).length, text, details: raw.details };
            await writeFile(file, JSON.stringify(result, null, 2) + '\n');
            console.log(JSON.stringify({ id: c.id, variant, model: raw.details?.model, thinking: raw.details?.thinking, status: raw.details?.status, elapsedMs: result.elapsedMs, characters: result.characters, toolCalls: raw.details?.toolCalls, turns: raw.details?.turns, warnings: raw.details?.warnings }));
            return result;
          } catch (error) {
            const result = { id: c.id, split: c.split, variant, goal: c.goal, elapsedMs: Math.round(performance.now() - start), error: error instanceof Error ? error.name : 'UnknownError', text: '', characters: 0 };
            await writeFile(file, JSON.stringify(result, null, 2) + '\n');
            console.log(JSON.stringify(result));
            return result;
          }
        };
        if (mode === 'benchmark') {
          let next = 0;
          await Promise.all(Array.from({ length: 3 }, async () => { while (next < cases.length) await run(cases[next++]); }));
        } else if (mode === 'boundaries') {
          const first = all.find((c: any) => c.id === 'd1');
          const other = all.find((c: any) => c.id === 'd3');
          const controller = new AbortController();
          const original = ctx.models.current();
          const alternate = ctx.models.resolve('openai-codex/gpt-5.5');
          if (!alternate || alternate.id === original.id) throw new Error('Distinct model unavailable for boundary scenario');
          const firstRun = run({ ...first, id: 'cancelled-astra' }, {}, controller.signal);
          await pi.setModel(alternate);
          pi.setThinkingLevel('medium');
          const secondRun = run({ ...other, id: 'current-after-switch' });
          const thirdRun = run({ ...other, id: 'explicit-astra' }, { model: `${original.provider}/${original.id}` });
          controller.abort();
          const results = await Promise.all([firstRun, secondRun, thirdRun]);
          const final = ctx.models.current();
          const outcome = { statuses: results.map((r: any) => r.details?.status), models: results.map((r: any) => r.details?.model), thinking: results.map((r: any) => r.details?.thinking), finalModel: `${final.provider}/${final.id}`, pluginModelSwitches: parentSwitches, parentMessages: parentMessages.length };
          await writeFile(join(folder, 'boundaries.json'), JSON.stringify(outcome, null, 2));
          if (outcome.statuses[0] !== 'aborted' || outcome.statuses[1] !== 'ready' || outcome.statuses[2] !== 'ready' || outcome.models[0] !== `${original.provider}/${original.id}` || outcome.models[1] !== `${alternate.provider}/${alternate.id}` || outcome.models[2] !== `${original.provider}/${original.id}` || final !== alternate || parentSwitches.length || parentMessages.length) throw new Error('Boundary scenario violated');
          console.log(JSON.stringify({ boundaries: 'passed', ...outcome }));
        } else if (mode === 'command') {
          const c = all.find((c: any) => c.id === 'd3');
          const model = ctx.models.current();
          await commands.get('jev').handler('plan ' + c.goal, ctx);
          const result = parentMessages.find((p: any) => p.message.customType === 'jev-planner');
          await writeFile(join(folder, 'command.json'), JSON.stringify({ result, parentSwitches, model: `${model.provider}/${model.id}`, finalModel: `${ctx.models.current()?.provider}/${ctx.models.current()?.id}` }, null, 2));
          if (!result || result.message.details?.status !== 'ready' || result.options?.triggerTurn !== false || result.options?.deliverAs !== 'nextTurn' || parentSwitches.length || ctx.models.current() !== model) throw new Error('Command planning violated');
          console.log(JSON.stringify({ command: 'passed', characters: result.message.content.length, model: result.message.details.model, triggerTurn: result.options.triggerTurn, pluginModelSwitches: parentSwitches.length }));
          let progressed: (() => void) | undefined;
          const commandUi = new Proxy(ctx.ui, {
            get(target, key) {
              if (key === 'setWidget') return (_name: string, value: unknown) => { if (value !== undefined) progressed?.(); };
              return Reflect.get(target, key, target);
            },
          });
          const commandCtx = new Proxy(ctx, {
            get(target, key) {
              if (key === 'hasUI') return true;
              if (key === 'ui') return commandUi;
              return Reflect.get(target, key, target);
            },
          });
          const longGoal = all.find((item: any) => item.id === 'd1').goal;
          for (const cancellation of ['stop', 'navigation']) {
            const started = new Promise<void>(resolve => { progressed = resolve; });
            const pending = commands.get('jev').handler('plan ' + longGoal, commandCtx);
            await Promise.race([started, pending.then(() => { throw new Error('Command settled before progress'); })]);
            const count = parentMessages.length;
            if (cancellation === 'stop') await commands.get('jev').handler('plan stop', commandCtx);
            else await hooks.get('session_before_tree')({}, commandCtx);
            await pending;
            if (parentMessages.length !== count) throw new Error('Cancelled command published a stale result');
          }
          // Tool planning must not replace the last successful command's goal.
          await run({ ...c, id: 'tool-does-not-own-goal', goal: 'Plan reading package.json without making changes.' });
          await commands.get('jev').handler('run', ctx);
          const handedOff = parentMessages.find((p: any) => p.message.customType === 'jev-orchestrator');
          if (!handedOff || !handedOff.message.content.includes(JSON.stringify(c.goal))) throw new Error('Explicit run lost the remembered command goal');
          await commands.get('jev').handler('stop', ctx);
          const lifecycle = { commandReady: true, commandStopSuppressedLateResult: true, navigationSuppressedLateResult: true, toolDidNotReplaceGoal: true, explicitRunReconciledRememberedGoal: true, implementationDispatched: false };
          await writeFile(join(folder, 'command-lifecycle.json'), JSON.stringify(lifecycle, null, 2));
          console.log(JSON.stringify({ commandLifecycle: 'passed', ...lifecycle }));
        }
        const after = await hashes();
        if (JSON.stringify(before) !== JSON.stringify(after)) throw new Error('Fixture changed during planning');
        console.log(JSON.stringify({ benchmark: 'complete', variant, split, mode, fixtureUnchanged: true, hashedFiles: Object.keys(before).length, pluginModelSwitches: parentSwitches.length }));
      } catch (error) {
        console.error('BENCHMARK FAILED', error instanceof Error ? error.message : 'unknown');
        process.exitCode = 1;
      } finally { ctx.shutdown(); }
    })();
  });
}

