import { JevOrchestrator } from './fixture/src/orchestrator.ts';
import { DEFAULT_ORCHESTRATOR } from './fixture/src/orchestration.ts';
let model = { id: 'active-model', provider: 'fixture', reasoning: true };
let idle = true;
const messages: any[] = [];
const api: any = { getThinkingLevel: () => 'medium', setThinkingLevel: () => { }, setModel: async (m: any) => { model = m; return true; }, sendMessage: (...args: any[]) => messages.push(args) };
const ctx: any = { cwd: import.meta.dir, isIdle: () => idle, hasPendingMessages: () => false, getAsyncJobSnapshot: () => null, models: { current: () => model, resolve: (id: string) => ({ id, provider: 'fixture', reasoning: true }) }, sessionManager: { getSessionId: () => 'boundary-fixture', getBranch: () => [] } };
const orchestrator = new JevOrchestrator(api, { config: async () => ({ main: {} as any, orchestrator: structuredClone(DEFAULT_ORCHESTRATOR) }), enabled: async () => true, notice: () => { } });
await orchestrator.start(ctx, 'First independent planning goal', true);
const parentModelChanged = model.id !== 'active-model';
let parallelCallRejected = false;
try { await orchestrator.start(ctx, 'Second independent planning goal', true); } catch { parallelCallRejected = true; }
await orchestrator.stop(ctx, 'fixture cleanup');
idle = false;
let busyCallerRejected = false;
try { await orchestrator.start(ctx, 'Planning from active AI caller', true); } catch { busyCallerRejected = true; }
const outcome = { variant: 'current-command-runtime', parentModelChanged, parallelCallRejected, busyCallerRejected, restoredModel: model.id, queuedWorkerTurns: messages.length };
await Bun.write(import.meta.dir + '/current-boundaries.json', JSON.stringify(outcome, null, 2) + '\n');
console.log(JSON.stringify(outcome));
if (parentModelChanged || parallelCallRejected || busyCallerRejected) throw new Error('Existing command fails the requested independent-current-model planning contract');

